entries[16164] = { ["name"] = "Elementarfokus", ["text"] = "Versetzt Euch in einen Freizauberzustand, nachdem Ihr mit einem Feuer-, Frost- oder Naturschadenszauber einen unregelmäßigen kritischen Treffer erzielt habt.\n\nDer Freizauberzustand verringert die Manakosten Eurer nächsten 2 Schadens- oder Heilzauber um 25%, erhöht den verursachten Zauberschaden um 20% und erhöht die Einzelzielheilung um 50%.\n(500ms Abklingzeit)" }
