entries[16190] = { ["name"] = "Totem der Manaflut", ["text"] = "Sofort 3 min Abklingzeit\nBeschwört ein Wassertotem mit [ Glyphe 'Totemische Lebenskraft' : 15 / 10]% der Gesundheit des Zaubernden zu dessen Füßen, das 16 Sek. anhält. Gruppen- und Schlachtzugsmitglieder im Umkreis von 40 Metern erhalten 200% der Willenskraft des zaubernden Schamanen (kurzzeitige Willenskraftboni werden aus der Berechnung ausgeschlossen)." }
