entries[16195] = { ["name"] = "Knöchelknochenbeutel herstellen", ["text"] = "Wirken in 2 sek.\nReagenzien:\nCharm Pouch (DND) , Magic Knucklebone (DND) (6)\nLegt 7 magische Knöchelknochen in den Glücksbringerbeutel, um einen Knöchelknochenbeutel zu erschaffen." }
entries[16196] = { ["name"] = "Rückstrom", ["text"] = "Während Euer Zauber 'Wasserschild' aktiv ist, gewinnt Ihr Mana zurück, wenn Eure direkten Heilzauber einen kritischen Effekt erzielen. Durch einen kritischen Effekt Eurer Zauber 'Welle der Heilung' oder 'Große Welle der Heilung' gewinnt Ihr ( 8849 * 100 / 100) Mana, durch einen kritischen Effekt Eurer Zauber 'Heilende Woge', 'Springflut' oder 'Leben entfesseln' gewinnt Ihr ( 8849 * 0.6 * 100 / 100) Mana und durch den kritischen Effekt von 'Kettenheilung' ( 8849 * 0.333 * 100 / 100) Mana." }
entries[16197] = { ["name"] = "Leerer Glücksbringerbeutel", ["text"] = "Wirken in 4 sek.\nLeeren, um einen Glücksbringerbeutel herzustellen." }
entries[16213] = { ["name"] = "Läuterung", ["text"] = "Erhöht die Effektivität Eurer Heilzauber um 25%, die von Euren Wassertotems hervorgerufene Heilung um zusätzliche 50% sowie die Heilung Eures Zaubers 'Heilender Regen' um zusätzliche 100%.\n\nAußerdem erhöhen von Euch gewirkte Heilungen die maximale Gesundheit Eurer Verbündeten um 10% des geheilten Wertes bis zu einem Maximum von 10% ihrer Gesundheit." }
