entries[16742] = { ["name"] = "Verzauberter Thoriumhelm", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nArkanitbarren (6), Verzauberter Thoriumbarren (16), Essenz der Erde (6), Großer Opal (2), Azerothischer Diamant\nVerzauberter Thoriumhelm\nWird beim Anlegen gebunden\nKopf Platte\n492 Rüstung\n+12 Stärke\n+25 Ausdauer\n+ 13 Ausweichen\nHaltbarkeit 80 / 80\n57" }
entries[16744] = { ["name"] = "Verzauberte Thoriumgamaschen", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nArkanitbarren (10), Verzauberter Thoriumbarren (20), Essenz des Wassers (6), Blauer Saphir (2), Gewaltiger Smaragd\nVerzauberte Thoriumgamaschen\nWird beim Anlegen gebunden\nBeine Platte\n533 Rüstung\n+20 Stärke\n+21 Ausdauer\n+ 12 Ausweichen\nHaltbarkeit 100 / 100\n58" }
entries[16745] = { ["name"] = "Verzauberte Thoriumbrustplatte", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nArkanitbarren (8), Verzauberter Thoriumbarren (24), Essenz der Erde (4), Essenz des Wassers (4), Gewaltiger Smaragd (2), Azerothischer Diamant (2)\nVerzauberte Thoriumbrustplatte\nWird beim Anlegen gebunden\nBrust Platte\n609 Rüstung\n+12 Stärke\n+26 Ausdauer\n+ 13 Ausweichen\nHaltbarkeit 135 / 135\n58" }
entries[16746] = { ["name"] = "Unverwundbarer Panzer", ["text"] = "Wirken in 15 sek.\nTools: Schmiedehammer\nReagenzien:\nArkanitbarren (30), Verzauberter Thoriumbarren (30), Gewaltiger Smaragd (6), Azerothischer Diamant (6)\nUnverwundbarer Panzer\nWird beim Anlegen gebunden\nBrust Kette\n510 Rüstung\n+ 20 Ausweichen\n43 Rüstung\nHaltbarkeit 165 / 165\n57\nAnlegen: Bei einem Treffer im Kampf besteht eine Chance von 5%, dass Ihr 3 Sek. lang gegen Nahkampfschaden immun werdet. Dieser Effekt kann maximal einmal alle 30 Sekunden auftreten. (Procchance: 5%, 30s Abklingzeit)" }
