entries[16790] = { ["name"] = "Niederschlagen", ["text"] = "Nahkampfreichweite\nSofort 5 sek. Abklingzeit\nFügt einem Feind sowie seinen nächsten Verbündeten 60 bis 80 Schaden zu und betäubt sie bis zu 2 Sek. lang. Wirkt auf maximal 3 Ziele." }
