entries[16798] = { ["name"] = "Verzauberndes Schlaflied", ["text"] = "30 Meter Reichweite\nWirken in 1 sek.\nLässt einen Feind bis zu 8 Sek. lang in Schlaf versinken. Jeglicher erlittene Schaden führt dazu, dass das Ziel erwacht. Es kann immer nur jeweils ein Ziel in Schlaf versetzt werden." }
entries[16799] = { ["name"] = "Frostblitz", ["text"] = "90 Mana 40 Meter Reichweite\nWirken in 1 sek.\nFügt einem Gegner Frostschaden zu und verringert 4 Sek. lang sein Bewegungstempo." }
