entries[16804] = { ["name"] = "Flammenschock", ["text"] = "20 Meter Reichweite\nSofort\nVerbrennt sofort einen Feind und fügt ihm dann 12 Sek. lang alle 3 Sek. zusätzlichen Feuerschaden zu." }
entries[16805] = { ["name"] = "Großbrand", ["text"] = "30 Meter Reichweite\nSofort\nSetzt einen Feind in Brand, fügt ihm im Verlauf von 5 Sek. insgesamt 750 Feuerschaden zu und versetzt ihn in Panik. Solange das Ziel betroffen ist, versengen die Flammen in regelmäßigen Abständen auch seine in der Nähe befindlichen Verbündeten und fügen ihnen 150 Schaden zu." }
entries[16806] = { ["name"] = "Großbrand", ["text"] = "Sofort\nFügt in der Nähe befindlichen Verbündeten 150 Feuerschaden zu." }
entries[16807] = { ["name"] = "Massenteleport", ["text"] = "Wirken in 20 sek.\nDies erzeugt einen Effekt bei dem zaubernden NSC, der ihn aussehen lässt, als wäre er gerade erst eingetroffen." }
entries[16809] = { ["name"] = "Spawn - Gallbrühschleimer" }
entries[16827] = { ["name"] = "Klaue", ["text"] = "25 Fokus 5 Meter Reichweite\nSpontanzauber 3 sek. Abklingzeit\nGreift einen Gegner mit den Klauen an und verursacht [(1.5 * (( 118 + 166 ) / 2 + Fernkampfangriffskraft * 0.168))] Schaden. Wenn Euer Begleiter über mehr als 50 Fokus verfügt, wird der Schaden von 'Klaue' um 100% erhöht, der Einsatz kostet jedoch 100% mehr Fokus." }
entries[16838] = { ["name"] = "Bansheeschrei", ["text"] = "Sofort 5 sek. Abklingzeit\nBringt nahe Gegner 4 Sek. lang zum Schweigen, sodass sie keine Zauber wirken können." }
entries[16843] = { ["name"] = "Purpurroter Furor", ["text"] = "Sofort\nGewährt dem Zaubernden 2 zusätzliche Angriffe und lässt ihn bei jedem erfolgreichen Treffer zusätzlichen Feuerschaden zufügen. Hält 4 Sek. lang an." }
entries[16844] = { ["name"] = "Purpurroter Furor", ["text"] = "Nahkampfreichweite\nSofort\nVerursacht beim Ziel Feuerschaden." }
entries[16856] = { ["name"] = "Tödlicher Stoß", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nVerursacht 200% Waffenschaden und verwundet das Ziel, verringert außerdem die Wirksamkeit jeglicher Heilung 5 Sek. lang um 50%." }
entries[16864] = { ["name"] = "Omen der Klarsicht", ["text"] = "Eure automatischen Angriffe gewähren eine kleine Chance, Euch in einen Freizauberzustand zu versetzen.\n\nDer Freizauberzustand verringert die Mana-, Wut- oder Energiekosten Eures nächsten Schadens- oder Heilzaubers mit Zauberzeit oder Eurer nächsten Offensivfähigkeit in Tiergestalt um 100%." }
entries[16865] = { ["name"] = "Spawn - Gallbrühschleimer" }
entries[16866] = { ["name"] = "Giftspucke", ["text"] = "30 Meter Reichweite\nWirken in 2.5 sek.\nSpuckt Gift auf in der Nähe befindliche Feinde; fügt ihnen erst Naturschaden und dann 10 Sek. lang alle 5 Sek. zusätzlichen Schaden zu." }
entries[16867] = { ["name"] = "Bansheefluch", ["text"] = "Sofort\nVerringert die Trefferchance von in der Nähe befindlichen Feinden 12 Sek. lang um 10%." }
entries[16868] = { ["name"] = "Wehklagen der Banshee", ["text"] = "40 Meter Reichweite\nWirken in 1.5 sek.\nHeult auf vor Schmerz und verursacht Schattenschaden bei einem Feind." }
entries[16869] = { ["name"] = "Eisgrab", ["text"] = "400 Mana 40 Meter Reichweite\nWirken in 1.5 sek.\nBetäubt einen Feind, sodass er sich 6 Sek. lang weder bewegen noch angreifen kann." }
entries[16870] = { ["name"] = "Freizaubern", ["text"] = "100 Meter Reichweite\nSofort\nDie Manakosten, Wutkosten oder Energiekosten Eures nächsten druidischen Schadenszaubers, Heilzaubers oder Eurer nächsten Offensivfähigkeit in Katzen- oder Bärengestalt sind um 100% verringert. Wirkt sich nicht auf 'Pflege' aus." }
entries[16871] = { ["name"] = "Kahlholzfluch", ["text"] = "30 Meter Reichweite\nSofort\nDer Feind wird vom Kahlholzfluch getroffen, der seinen Magiewiderstand um 164 verringert. Kann bis zu 3-mal angewendet werden." }
entries[16872] = { ["name"] = "Schlachtzugsstärkung Stufe 60" }
