entries[16877] = { ["name"] = "Dornen", ["text"] = "30 Meter Reichweite\nSofort\nAus dem befreundeten Ziel sprießen Dornen, die jedem Angreifer 18 Naturschaden zufügen. Hält 10 Min. lang an." }
