entries[16881] = { ["name"] = "Wasseratmung", ["text"] = "30 Meter Reichweite\nSofort\nErmöglicht dem Zaubernden 10 Min. lang das Atmen unter Wasser." }
entries[16882] = { ["name"] = "Große Unsichtbarkeit entdecken", ["text"] = "30 Meter Reichweite\nSofort\nErmöglicht dem befreundeten Ziel, 10 Min. lang große Unsichtbarkeit zu entdecken." }
