entries[16888] = { ["name"] = "Intelligenz IX", ["text"] = "Sofort\nErhöht die Intelligenz 1 Stunde lang um 40." }
entries[16889] = { ["name"] = "Großes Arkanelixier", ["text"] = "Sofort\nErhöht die Schadenswirkung von Zaubern 30 Min. lang um 35." }
entries[16890] = { ["name"] = "Regeneration IV", ["text"] = "Sofort\n1 Stunde lang alle 5 Sekunden 4 Gesundheit regenerieren." }
entries[16891] = { ["name"] = "Schattenschutz", ["text"] = "Sofort\nAbsorbiert 675 bis 1125 Schattenschaden. Hält 1 Stunde lang an." }
entries[16892] = { ["name"] = "Heiligschutz", ["text"] = "Sofort\nAbsorbiert 300 bis 500 Heiligschaden. Hält 1 Stunde lang an." }
entries[16893] = { ["name"] = "Naturschutz", ["text"] = "Sofort\nAbsorbiert 1350 bis 2250 Naturschaden. Hält 1 Stunde lang an." }
