entries[16895] = { ["name"] = "Frostschutz", ["text"] = "Sofort\nAbsorbiert 1350 bis 2250 Frostschaden. Hält 1 Stunde lang an." }
entries[16898] = { ["name"] = "Lohe", ["text"] = "30 Meter Reichweite\nSofort\nVerbrennt den Feind und fügt ihm im Verlauf von 30 Sek. 639 Schaden zu." }
entries[16908] = { ["name"] = "Magiebannung", ["text"] = "30 Meter Reichweite\nSofort 8 sek. Abklingzeit\nBannt einen magischen Effekt, der auf dem augenblicklichen Feind liegt." }
entries[16914] = { ["name"] = "Hurrikan", ["text"] = "50.3% von Grundmana 30 Meter Reichweite\nKanalisiert (Wirken in 10 sek.)\nErzeugt einen wütenden Sturm im Zielgebiet, der Gegnern alle 1.00 Sek. 339 Naturschaden zufügt [ Glyphe 'Hurrikan' : und ihr Bewegungstempo um 50% verringert ]. Hält 10 Sek. lang an. Der Druide muss seine Kräfte kanalisieren, um den Zauber aufrechtzuerhalten." }
entries[16916] = { ["name"] = "Stärke des Champions", ["text"] = "40 Meter Reichweite\nSofort\nSich selbst um 269 heilen und Stärke 30 Sek. lang um 415 erhöhen." }
entries[16921] = { ["name"] = "Kettenblitzschlag", ["text"] = "30 Meter Reichweite\nSofort\nÜberzieht bis zu 3 Ziele mit 709 Naturschaden." }
entries[16927] = { ["name"] = "Kälte", ["text"] = "30 Meter Reichweite\nSofort\nBewegungstempo des Ziels um 30% verlangsamt und Zeit zwischen Angriffen um 25% erhöht. Hält 5 Sek. lang an." }
entries[16928] = { ["name"] = "Rüstungszertrümmerung", ["text"] = "30 Meter Reichweite\nSofort\nVerringert die Rüstung eines Feindes um 1133 . Bis zu 3-mal stapelbar." }
entries[16931] = { ["name"] = "Dickes Fell", ["text"] = "Erhöht den Rüstungsbonus in Bärengestalt auf 330%, verringert sämtlichen erlittenen Magieschaden um 25%, verringert sämtlichen erlittenen körperlichen Schaden um 12% und verringert die Chance, kritische Treffer zu erleiden, um 6%.\n\nVerringert zusätzlich die Abklingzeit von 'Baumrinde' um 30 Sek." }
entries[16939] = { ["name"] = "Rache des Vorfahren", ["text"] = "30 Meter Reichweite\nSofort\nGruppenmitglieder haben eine Chance, ihren kritischen Trefferwert um 270 zu erhöhen. Hält 20 Sek. lang an." }
entries[16949] = { ["name"] = "Instinkt der Wildnis", ["text"] = "Benötigt Katzengestalt\nVerringert die Chance, dass Gegner Euch beim Schleichen entdecken." }
entries[16953] = { ["name"] = "Urfuror", ["text"] = "100 Meter Reichweite\nSofort\nBenötigt Katzengestalt\nJedes Mal, wenn Ihr einen kritischen Treffer mit einer Einzelzielfähigkeit erzielt, die Combopunkte erzeugt, wird dem Ziel ein zusätzlicher Combopunkt hinzugefügt." }
entries[16959] = { ["name"] = "Urfuror", ["text"] = "Sofort\nBenötigt Bärengestalt\nIhr erhaltet zusätzlich 15 Wut, wenn Ihr mit Euren automatischen Angriffen oder mit 'Zerfleischen' einen kritischen Treffer erzielt." }
entries[16960] = { ["name"] = "Thoriumgroßschwert", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nThoriumbarren (10), Verdichteter Schleifstein (2), Unverwüstliches Leder (4)" }
entries[16961] = { ["name"] = "Urfuror", ["text"] = "Benötigt Katzengestalt, Bärengestalt\nIhr erhaltet zusätzlich 15 Wut, wenn Ihr mit Euren automatischen Angriffen oder mit 'Zerfleischen' einen kritischen Treffer erzielt. Außerdem wird Eurem Ziel ein zusätzlicher Combopunkt hinzugefügt, wenn eine Eurer Combopunkte erzeugenden Einzelzielfähigkeiten einen kritischen Treffer erzielt." }
entries[16965] = { ["name"] = "Kahlholzhacke", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nThoriumbarren (30), Essenz des Lebens (6), Wildranke (6), Großer Opal (6), Verdichteter Schleifstein (2), Unverwüstliches Leder (8)" }
entries[16967] = { ["name"] = "Veredelter Thoriumhammer", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nThoriumbarren (30), Goldbarren (4), Echtsilberbarren (2), Blauer Saphir (2), Unverwüstliches Leder (4)" }
entries[16969] = { ["name"] = "Verschnörkelte Thoriumhandaxt", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nThoriumbarren (10), Großer Opal (2), Verdichteter Schleifstein (2), Unverwüstliches Leder (4)\nVerschnörkelte Thoriumhandaxt\nWird beim Aufheben gebunden\nEinhändig Axt\n43 - 81 Schaden Tempo 1.90\n(32.63 Schaden pro Sekunde)\n+10 Stärke\nHaltbarkeit 75 / 75\n50" }
entries[16970] = { ["name"] = "Dämmerungsschneide", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nThoriumbarren (30), Verzauberter Thoriumbarren (4), Sternrubin (4), Blauer Saphir (4), Verdichteter Schleifstein (2), Unverwüstliches Leder (4)\nDämmerungsschneide\nWird beim Anlegen gebunden\nEinhändig Axt\n53 - 100 Schaden Tempo 2.10\n(36.43 Schaden pro Sekunde)\nErhöht Eure kritische Trefferwertung um + 14.\nHaltbarkeit 90 / 90\n50" }
entries[16971] = { ["name"] = "Gewaltige Thoriumstreitaxt", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nThoriumbarren (12), Verdichteter Schleifstein (6), Unverwüstliches Leder (6)\nGewaltige Thoriumstreitaxt\nWird beim Anlegen gebunden\nZweihändig Axt\n114 - 172 Schaden Tempo 3.30\n(43.33 Schaden pro Sekunde)\nErhöht Eure Waffenkundewertung um + 24.\nHaltbarkeit 85 / 85\n51" }
entries[16973] = { ["name"] = "Verzauberter Kampfhammer", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nThoriumbarren (20), Verzauberter Thoriumbarren (6), Gewaltiger Smaragd (2), Mächtiges Mojo (4), Unverwüstliches Leder (4)\nVerzauberter Kampfhammer\nWird beim Anlegen gebunden\nZweihändig Streitkolben\n100 - 150 Schaden Tempo 2.60\n(48.08 Schaden pro Sekunde)\n+ 20 Parieren\nErhöht Eure Trefferwertung um + 20.\nHaltbarkeit 100 / 100\n51" }
entries[16974] = { ["name"] = "Schnelligkeit des Raubtiers", ["text"] = "Eure Finishing-Moves gewähren pro Combopunkt eine Chance von 20%, dass Euer nächster Einsatz von 'Wucherwurzeln', 'Heilende Berührung', 'Winterschlaf' oder 'Wiedergeburt' zu einem kostenlosen Spontanzauber wird, der in jeder Gestalt gewirkt werden kann." }
entries[16978] = { ["name"] = "Loderflammenrapier", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nVerzauberter Thoriumbarren (10), Essenz des Feuers (4), Herz des Feuers (4), Azerothischer Diamant (2), Verdichteter Schleifstein (2)\nLoderflammenrapier\nWird beim Anlegen gebunden\nEinhändig Schwert\n44 - 82 Schaden Tempo 1.70\n(37.06 Schaden pro Sekunde)\nHaltbarkeit 90 / 90\n51\nTrefferchance: Verbrennt den Feind und fügt ihm im Verlauf von 30 Sek. 128 Schaden zu." }
entries[16979] = { ["name"] = "Wilde Attacke", ["text"] = "8 - 25 Meter Reichweite\nSofort 15 sek. Abklingzeit\nBenötigt Bärengestalt\nStürmt auf einen Gegner zu und macht ihn 4 Sek. lang bewegungsunfähig." }
entries[16980] = { ["name"] = "Runenschneide", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nThoriumbarren (30), Großer Opal (2), Verdichteter Schleifstein (2), Unverwüstliches Leder (4)" }
entries[16982] = { ["name"] = "Feuerkugel", ["text"] = "Sofort\nGewährt eine Chance, beim Schlagen des Feindes 471 Feuerschaden zuzufügen.\n(Procchance: 1%)" }
entries[16983] = { ["name"] = "Beschaulichkeit", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nVerzauberter Thoriumbarren (6), Arkanitbarren (2), Mächtiges Mojo (4), Großer Opal (2), Blauer Saphir (2), Gewaltiger Smaragd\nBeschaulichkeit\nWird beim Anlegen gebunden\nEinhändig Streitkolben\n52 - 98 Schaden Tempo 2.00\n(37.50 Schaden pro Sekunde)\nHaltbarkeit 90 / 90\n52\nTrefferchance: Bannt einen magischen Effekt, der auf dem augenblicklichen Feind liegt." }
entries[16984] = { ["name"] = "Vulkanischer Hammer", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nThoriumbarren (30), Herz des Feuers (4), Sternrubin (4), Unverwüstliches Leder (4)\nVulkanischer Hammer\nWird beim Anlegen gebunden\nEinhändig Streitkolben\n60 - 113 Schaden Tempo 2.50\n(34.60 Schaden pro Sekunde)\nHaltbarkeit 75 / 75\n53\nTrefferchance: Schleudert eine glühende Kugel, die 149 Feuerschaden sowie zusätzlich 6 Sek. lang insgesamt 18 Schaden verursacht." }
entries[16985] = { ["name"] = "Verderbnis", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nThoriumbarren (40), Arkanitbarren (2), Dämonische Rune (16), Essenz des Untodes (8), Blauer Saphir (2), Verdichteter Schleifstein (2), Unverwüstliches Leder (4)\nVerderbnis\nWird beim Aufheben gebunden\nZweihändig Schwert\n119 - 179 Schaden Tempo 3.00\n(49.67 Schaden pro Sekunde)\n+30 Stärke\n+30 Ausdauer\nErhöht Eure Trefferwertung um - -39.\nHaltbarkeit 100 / 100\n53" }
entries[16986] = { ["name"] = "Blutkralle", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nVerzauberter Thoriumbarren (10), Arkanitbarren (10), Dämonische Rune (8), Sternrubin (10), Verdichteter Schleifstein (2)" }
entries[16987] = { ["name"] = "Dunkelspeer", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nVerzauberter Thoriumbarren (20), Mächtiges Mojo (20), Gewaltiger Smaragd (2), Azerothischer Diamant (2), Verdichteter Schleifstein (2)" }
entries[16988] = { ["name"] = "Hammer der Titanen", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nThoriumbarren (50), Arkanitbarren (15), Wächterstein (4), Verzaubertes Leder (6), Essenz der Erde (10)\nHammer der Titanen\nWird beim Anlegen gebunden\nZweihändig Streitkolben\n163 - 246 Schaden Tempo 3.80\n(53.82 Schaden pro Sekunde)\n+15 Stärke\nHaltbarkeit 100 / 100\n58\nTrefferchance: Betäubt ein Ziel 3 Sek. lang." }
entries[16989] = { ["name"] = "Flagge aufstellen", ["text"] = "20 Meter Reichweite\nWirken in 2.3 sek.\nStellt das Banner der Geißel im vorgeschobenen Stützpunkt des Scharlachroten Kreuzzugs in den Westlichen Pestländern auf." }
entries[16990] = { ["name"] = "Arkanitchampion", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nArkanitbarren (15), Azerothischer Diamant (8), Rechtschaffene Kugel , Großer Opal (4), Verzaubertes Leder (8), Verdichteter Schleifstein (2)\nArkanitchampion\nWird beim Anlegen gebunden\nZweihändig Schwert\n129 - 194 Schaden Tempo 3.00\n(53.83 Schaden pro Sekunde)\nHaltbarkeit 100 / 100\n58\nTrefferchance: Sich selbst um 269 heilen und Stärke 30 Sek. lang um 153 erhöhen." }
entries[16991] = { ["name"] = "Vernichter", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nThoriumbarren (40), Arkanitbarren (12), Essenz des Untodes (10), Gewaltiger Smaragd (8), Verdichteter Schleifstein (2), Verzaubertes Leder (4)\nVernichter\nWird beim Anlegen gebunden\nEinhändig Axt\n49 - 92 Schaden Tempo 1.70\n(41.47 Schaden pro Sekunde)\nHaltbarkeit 90 / 90\n58\nTrefferchance: Verringert die Rüstung eines Feindes um 256 . Bis zu 3-mal stapelbar." }
entries[16992] = { ["name"] = "Frostwache", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nArkanitbarren (18), Blauer Saphir (8), Azerothischer Diamant (8), Essenz des Wassers (4), Verdichteter Schleifstein (2), Verzaubertes Leder (4)\nFrostwache\nWird beim Anlegen gebunden\nEinhändig Schwert\n66 - 124 Schaden Tempo 2.30\n(41.30 Schaden pro Sekunde)\nHaltbarkeit 90 / 90\n58\nTrefferchance: Bewegungstempo des Ziels um 30% verlangsamt und Zeit zwischen Angriffen um 25% erhöht. Hält 5 Sek. lang an." }
entries[16993] = { ["name"] = "Meisterlicher Sturmhammer", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nVerzauberter Thoriumbarren (20), Gewaltiger Smaragd (8), Großer Opal (8), Essenz der Erde (6), Verzaubertes Leder (4)\nMeisterlicher Sturmhammer\nWird beim Anlegen gebunden\nEinhändig Streitkolben\n58 - 108 Schaden Tempo 2.00\n(41.50 Schaden pro Sekunde)\nHaltbarkeit 90 / 90\n57\nTrefferchance: Überzieht bis zu 3 Ziele mit 160 Naturschaden." }
entries[16994] = { ["name"] = "Arkanitschnitter", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nArkanitbarren (20), Verzaubertes Leder (6), Verdichteter Schleifstein (2)\nArkanitschnitter\nWird beim Anlegen gebunden\nZweihändig Axt\n153 - 256 Schaden Tempo 3.80\n(53.82 Schaden pro Sekunde)\n+13 Ausdauer\n+ 62 Angriffskraft.\nHaltbarkeit 100 / 100\n58" }
entries[16995] = { ["name"] = "Herzsucher", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nArkanitbarren (10), Verzauberter Thoriumbarren (10), Verzaubertes Leder (2), Sternrubin (6), Azerothischer Diamant (6), Großer Opal (6), Verdichteter Schleifstein (4)\nHerzsucher\nWird beim Anlegen gebunden\nEinhändig Dolch\n49 - 92 Schaden Tempo 1.70\n(41.47 Schaden pro Sekunde)\n+4 Stärke\nErhöht Eure kritische Trefferwertung um + 14.\nHaltbarkeit 65 / 65\n58" }
