entries[17007] = { ["name"] = "Rudelführer", ["text"] = "Benötigt Katzengestalt, Bärengestalt\nIn Katzen- oder Bärengestalt erhöht Ihr die kritische Trefferchance aller Gruppen- und Schlachtzugsmitglieder in einem Umkreis von 100 Metern um 5%.\n\nZusätzlich werdet Ihr, wenn Ihr in Katzen- oder Bärengestalt kritische Treffer erzielt, um 4% Eurer gesamten Gesundheit geheilt und gewinnt 8% Eures maximalen Manas hinzu. Dieser Effekt kann nur ein Mal alle 6 Sek. eintreten.\n(6s Abklingzeit)" }
