entries[17634] = { ["name"] = "Trank der Versteinerung", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nSteinschuppenöl (7), Kristallphiole\n(2)\n50\nBenutzen: Ihr werdet zu Stein und absorbiert 6000 Schaden aus jeglicher Schadensquelle, allerdings könnt Ihr während dieser Zeit weder angreifen noch Euch bewegen oder Zauber wirken. Hält 30 Sek. lang an. (1 Min Abklingzeit)" }
entries[17635] = { ["name"] = "Fläschchen der Titanen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGromsblut (7), Steinschuppenöl (3), Schwarzer Lotus , Kristallphiole\n(2)\n50\nBenutzen: Erhöht die maximale Gesundheit des Spielers 1 Stunde lang um 400 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)" }
entries[17636] = { ["name"] = "Fläschchen der destillierten Weisheit", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nTraumblatt (7), Eiskappe (3), Schwarzer Lotus , Kristallphiole\n(2)\n50\nBenutzen: Erhöht die Intelligenz 1 Stunde lang um 65 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)" }
entries[17637] = { ["name"] = "Fläschchen der obersten Macht", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nTraumblatt (7), Bergsilbersalbei (3), Schwarzer Lotus , Kristallphiole\n(2)\n50\nBenutzen: Erhöht die Zaubermacht 1 Stunde lang um 70 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)" }
