entries[17962] = { ["name"] = "Feuersbrunst", ["text"] = "1% von Grundmana 40 Meter Reichweite\nSofort 12 sek. Wiederaufladung\n2 Aufladungen\nDer Gegner explodiert sofort und erleidet 1843 Feuerschaden [ Glyphe 'Feuersbrunst' : Das Ziel wird außerdem 5 Sek. lang um 50% verlangsamt / .\n\nWenn 'Feuerbrand' auf dem Ziel aktiv ist, wird sein Bewegungstempo 5 Sek. lang um 50% verringert.]\nErzeugt instabile Funken. Kritische Treffer verdoppeln diesen Effekt." }
